fn compose(self, factor: f32) -> Self {
        if self.kw == FontSizeKeyword::None {
            return self;
        }
        KeywordInfo {
            kw: self.kw,
            factor: self.factor * factor,
            offset: self.offset * factor,
        }
    }

fn to_length(&self, cx: &Context) -> NonNegativeLength {
        let font = cx.style().get_font();

        #[cfg(feature = "servo")]
        let family = &font.font_family.families;
        #[cfg(feature = "gecko")]
        let family = &font.mFont.family.families;

        let generic = family
            .single_generic()
            .unwrap_or(computed::GenericFontFamily::None);

        #[cfg(feature = "gecko")]
        let base_size = cx
            .device()
            .base_size_for_generic(&font.mLanguage.0, generic);
        #[cfg(feature = "servo")]
        let base_size = cx.device().base_size_for_generic(generic);

        self.to_length_without_context(cx.quirks_mode, base_size)
    }

pub fn to_computed_value_against(
        &self,
        context: &Context,
        base_size: FontBaseSize,
        line_height_base: LineHeightBase,
    ) -> computed::FontSize {
        let compose_keyword = |factor| {
            context
                .style()
                .get_parent_font()
                .slow_clone_font_size()
                .keyword_info
                .compose(factor)
        };
        let mut info = KeywordInfo::none();
        let size =
            match *self {
                FontSize::Length(LengthPercentage::Length(ref l)) => {
                    if l.length_unit() == LengthUnit::Em {
                        // If the parent font was keyword-derived, this is
                        // too. Tack the em unit onto the factor
                        info = compose_keyword(l.unitless_value());
                    }
                    let result =
                        l.to_computed_value_with_base_size(context, base_size, line_height_base);
                    if l.should_zoom_text() {
                        context.maybe_zoom_text(result)
                    } else {
                        result
                    }
                },
                FontSize::Length(LengthPercentage::Percentage(pc)) => {
                    // If the parent font was keyword-derived, this is too.
                    // Tack the % onto the factor
                    info = compose_keyword(pc.get());
                    (base_size.resolve(context).computed_size() * pc.get()).normalized()
                },
                FontSize::Length(LengthPercentage::Calc(ref calc)) => {
                    let calc = calc.to_computed_value_zoomed(context, base_size, line_height_base);
                    calc.resolve(base_size.resolve(context).computed_size())
                },
                FontSize::Keyword(i) => {
                    if i.kw.is_math() {
                        // Scaling is done in recompute_math_font_size_if_needed().
                        info = compose_keyword(1.);
                        // i.kw will always be FontSizeKeyword::Math here. But writing it this
                        // allows this code to compile for servo where the Math variant is cfg'd out.
                        info.kw = i.kw;
                        NoCalcLength::from_em(1.).to_computed_value_with_base_size(
                            context,
                            base_size,
                            line_height_base,
                        )
                    } else {
                        // As a specified keyword, this is keyword derived
                        info = i;
                        i.to_computed_value(context).clamp_to_non_negative()
                    }
                },
                FontSize::Smaller => {
                    info = compose_keyword(1. / LARGER_FONT_SIZE_RATIO);
                    NoCalcLength::from_em(1. / LARGER_FONT_SIZE_RATIO)
                        .to_computed_value_with_base_size(context, base_size, line_height_base)
                },
                FontSize::Larger => {
                    info = compose_keyword(LARGER_FONT_SIZE_RATIO);
                    NoCalcLength::from_em(LARGER_FONT_SIZE_RATIO).to_computed_value_with_base_size(
                        context,
                        base_size,
                        line_height_base,
                    )
                },
                FontSize::System(_) => {
                    #[cfg(feature = "servo")]
                    {
                        unreachable!()
                    }
                    #[cfg(feature = "gecko")]
                    {
                        context
                            .cached_system_font
                            .as_ref()
                            .unwrap()
                            .font_size
                            .computed_size()
                            .zoom(context.builder.effective_zoom)
                    }
                },
            };
        let size = NonNegative(Self::quantize_font_size(size));
        computed::FontSize {
            computed_size: size,
            used_size: size,
            keyword_info: info,
        }
    }

pub fn resolve(&self, context: &Context) -> computed::FontSize {
        let style = context.style();
        match *self {
            Self::CurrentStyle => style.get_font().slow_clone_font_size(),
            Self::InheritedStyle => {
                // If we're using the size from our inherited style, we still need to apply our
                // own zoom.
                let zoom = style.effective_zoom_for_inheritance;
                style.get_parent_font().slow_clone_font_size().zoom(zoom)
            },
        }
    }

pub fn zoom(&self, zoom: Zoom) -> Self {
        Self {
            computed_size: NonNegative(Length::new(zoom.zoom(self.computed_size.0.px()))),
            used_size: NonNegative(Length::new(zoom.zoom(self.used_size.0.px()))),
            keyword_info: self.keyword_info,
        }
    }

pub fn medium() -> Self {
        Self {
            computed_size: NonNegative(Length::new(specified::FONT_MEDIUM_PX)),
            used_size: NonNegative(Length::new(specified::FONT_MEDIUM_PX)),
            keyword_info: KeywordInfo::medium(),
        }
    }

pub fn copy_font_size_from(&mut self, other: &Self) {
        self.mScriptUnconstrainedSize = other.mScriptUnconstrainedSize;

        self.mSize = other.mScriptUnconstrainedSize;
        // NOTE: Intentionally not copying from mFont.size. The cascade process
        // recomputes the used size as needed.
        self.mFont.size = other.mSize;
        self.mFontSizeKeyword = other.mFontSizeKeyword;

        // TODO(emilio): Should we really copy over these two?
        self.mFontSizeFactor = other.mFontSizeFactor;
        self.mFontSizeOffset = other.mFontSizeOffset;
    }

fn recompute_zoom_dependent_inherited_lengths(&self, context: &mut computed::Context) {
        debug_assert!(self.seen.longhands.contains(LonghandId::Zoom));
        for prop in LonghandIdSet::zoom_dependent_inherited_properties().iter() {
            if self.seen.longhands.contains(prop) {
                continue;
            }
            let declaration = PropertyDeclaration::css_wide_keyword(prop, CSSWideKeyword::Inherit);
            unsafe {
                self.do_apply_declaration(context, prop, &declaration);
            }
        }
    }

fn recompute_keyword_font_size_if_needed(&self, context: &mut computed::Context) {
        use crate::values::computed::ToComputedValue;

        if !self.seen.longhands.contains(LonghandId::XLang)
            && !self.seen.longhands.contains(LonghandId::FontFamily)
        {
            return;
        }

        let new_size = {
            let font = context.builder.get_font();
            let info = font.slow_clone_font_size().keyword_info;
            let new_size = match info.kw {
                specified::FontSizeKeyword::None => return,
                _ => {
                    context.for_non_inherited_property = false;
                    specified::FontSize::Keyword(info).to_computed_value(context)
                },
            };

            #[cfg(feature = "gecko")]
            if font.mScriptUnconstrainedSize == new_size.computed_size {
                return;
            }

            new_size
        };

        context.builder.mutate_font().set_font_size(new_size);
    }

fn unzoom_fonts_if_needed(&self, builder: &mut StyleBuilder) {
        debug_assert!(self.seen.longhands.contains(LonghandId::XTextScale));

        let parent_text_scale = *builder.get_parent_font().get__x_text_scale();
        let text_scale = *builder.get_font().get__x_text_scale();
        if parent_text_scale == text_scale {
            return;
        }
        debug_assert_ne!(
            parent_text_scale.text_zoom_enabled(),
            text_scale.text_zoom_enabled(),
            "There's only one value that disables it"
        );
        debug_assert!(
            !text_scale.text_zoom_enabled(),
            "We only ever disable text zoom never enable it"
        );
        let device = builder.device;
        builder.mutate_font().unzoom_fonts(device);
    }

